import{_ as t,C as a,o as l,c as r,j as s,a as d,G as n,a3 as c}from"./chunks/framework.B6x8LOwa.js";const v=JSON.parse('{"title":"环境搭建","description":"开发 InkCanvas For Class 所需的工具与环境","frontmatter":{"title":"环境搭建","description":"开发 InkCanvas For Class 所需的工具与环境"},"headers":[],"relativePath":"cn/dev/getting-started/environment.md","filePath":"cn/dev/getting-started/environment.md"}'),p={name:"cn/dev/getting-started/environment.md"};function h(k,e,g,u,b,m){const i=a("ArticleMetadata"),o=a("HelpUsImprove");return l(),r("div",null,[e[0]||(e[0]=s("h1",{id:"环境搭建",tabindex:"-1"},[d("环境搭建 "),s("a",{class:"header-anchor",href:"#环境搭建","aria-label":'Permalink to "环境搭建"'},"​")],-1)),n(i),n(o),e[1]||(e[1]=c(`<h2 id="必需工具" tabindex="-1">必需工具 <a class="header-anchor" href="#必需工具" aria-label="Permalink to &quot;必需工具&quot;">​</a></h2><h3 id="net-6-sdk" tabindex="-1">.NET 6 SDK <a class="header-anchor" href="#net-6-sdk" aria-label="Permalink to &quot;.NET 6 SDK&quot;">​</a></h3><p>项目的 TargetFramework 是 <code>net6.0-windows10.0.19041.0</code>，需要：</p><ul><li><a href="https://dotnet.microsoft.com/download/dotnet/6.0" target="_blank" rel="noreferrer">.NET 6.0 SDK</a>（最低版本 6.0.100）</li><li>Windows 10 SDK 19041 或更高版本（Visual Studio 安装程序会自动安装）</li></ul><p>验证安装：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sdks</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 应看到 6.0.x</span></span></code></pre></div><h3 id="visual-studio-2022" tabindex="-1">Visual Studio 2022 <a class="header-anchor" href="#visual-studio-2022" aria-label="Permalink to &quot;Visual Studio 2022&quot;">​</a></h3><p>推荐 VS 2022（17.0 或更高），需要安装以下工作负载：</p><ul><li><strong>.NET 桌面开发</strong>（含 WPF 和 Windows Forms）</li><li><strong>通用 Windows 平台开发</strong>（提供 Windows 10 SDK）</li></ul><p>可选但推荐：</p><ul><li><strong>Visual Studio 扩展开发</strong>（如果你要改 PowerPoint Add-in 项目）</li></ul><h3 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to &quot;Git&quot;">​</a></h3><p>克隆仓库需要 <a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a>。</p><h2 id="克隆仓库" tabindex="-1">克隆仓库 <a class="header-anchor" href="#克隆仓库" aria-label="Permalink to &quot;克隆仓库&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/InkCanvasForClass/community.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> community</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> net6</span></span></code></pre></div><p><strong>重要</strong>：主分支是 <code>net6</code>，不是 <code>master</code>。所有 PR 都要提交到 <code>net6</code>。</p><h2 id="目录结构速览" tabindex="-1">目录结构速览 <a class="header-anchor" href="#目录结构速览" aria-label="Permalink to &quot;目录结构速览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>community/</span></span>
<span class="line"><span>├── Ink Canvas/               # 主程序（WPF）</span></span>
<span class="line"><span>├── InkCanvas.PluginSdk/     # 插件 SDK（打 NuGet 包）</span></span>
<span class="line"><span>├── InkCanvas.Controls/      # 控件库</span></span>
<span class="line"><span>├── InkCanvas.IACoreHelper/  # 辅助进程（x86）</span></span>
<span class="line"><span>├── InkCanvas.SettingsTreeView/  # 设置页树形控件</span></span>
<span class="line"><span>├── InkCanvas.PPTAgent.Contracts/  # PPT Agent 契约</span></span>
<span class="line"><span>├── build/                    # Inno Setup 打包脚本</span></span>
<span class="line"><span>├── version.json             # Nerdbank.GitVersioning 版本配置</span></span>
<span class="line"><span>└── Directory.Build.props    # 全局注入 Nerdbank.GitVersioning</span></span></code></pre></div><p>磁盘上还有 <code>InkCanvas.PowerPointAddIn</code> 和 <code>InkCanvas.NativeInk.Tests</code>，但它们未加入 <code>Ink Canvas.sln</code>。</p><h2 id="首次构建" tabindex="-1">首次构建 <a class="header-anchor" href="#首次构建" aria-label="Permalink to &quot;首次构建&quot;">​</a></h2><p>打开 <code>Ink Canvas.sln</code>，选择 <code>Debug|Any CPU</code> 或 <code>Debug|x64</code>，按 <code>Ctrl+Shift+B</code> 构建。</p><p>首次构建时 Nerdbank.GitVersioning 会以 <code>version.json</code>（当前 <code>1.7.19.9</code>）作为基础版本，再结合 git 提交历史计算最终版本号，自动生成 <code>ThisAssembly.cs</code>。也就是说，即使在没有可用 git 信息的情况下，项目仍然有一个明确的基础版本可用；主程序在缺少提交缩写时会回退为 <code>UNKNOWN</code>。</p><p><strong>IACoreHelper 平台问题</strong>：<code>InkCanvas.IACoreHelper</code> 强制为 <code>x86</code>（因为 IACore 原生库是 32 位），在解决方案配置里所有平台都被映射到 <code>x86</code>。如果你用 <code>Any CPU</code> 构建整个解决方案，主程序会是 <code>Any CPU</code>（启动时 JIT 成 64 位），但 IACoreHelper 始终是 32 位——这是正常的。</p><h2 id="调试启动" tabindex="-1">调试启动 <a class="header-anchor" href="#调试启动" aria-label="Permalink to &quot;调试启动&quot;">​</a></h2><p>设置 <code>InkCanvasForClass</code> 为启动项目，按 <code>F5</code> 启动调试。</p><p>启动流程详见 <a href="/website/cn/dev/core/startup">启动流程</a>。</p><p>如果启动失败，看日志：日志写在<strong>程序目录</strong>下的 <code>Logs\\</code> 文件夹（<code>App.RootPath</code> 即 <code>AppDomain.CurrentDomain.SetupInformation.ApplicationBase</code>），文件名形如 <code>Log_yyyy-MM-dd-HH-mm-ss.txt</code>。崩溃转储在同级的 <code>Crashes\\</code> 目录。</p><div class="tip custom-block"><p class="custom-block-title">注意</p><p><code>Logs</code> 文件夹超过 5 MB 时会被 <code>LogHelper.CheckAndCleanLogsFolder()</code> 自动清空，排查问题时记得及时备份。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="构建报错-nbgv002-找不到-git-仓库" tabindex="-1">构建报错 <code>NBGV002</code>：找不到 git 仓库 <a class="header-anchor" href="#构建报错-nbgv002-找不到-git-仓库" aria-label="Permalink to &quot;构建报错 \`NBGV002\`：找不到 git 仓库&quot;">​</a></h3><p>Nerdbank.GitVersioning 要求代码在 git 仓库里。如果你下载的是 zip 而非 clone，或者在非 git 目录下打开了 sln，会报此错。解决方法：用 <code>git clone</code> 获取代码。</p><h3 id="iacorehelper-构建警告平台不匹配" tabindex="-1">IACoreHelper 构建警告平台不匹配 <a class="header-anchor" href="#iacorehelper-构建警告平台不匹配" aria-label="Permalink to &quot;IACoreHelper 构建警告平台不匹配&quot;">​</a></h3><p>这是预期行为。IACoreHelper 必须是 x86，与主程序的 AnyCPU 不匹配。可以忽略警告，或在解决方案配置管理器里把 IACoreHelper 从某些平台的构建中移除。</p><h3 id="office-interop-报错" tabindex="-1">Office Interop 报错 <a class="header-anchor" href="#office-interop-报错" aria-label="Permalink to &quot;Office Interop 报错&quot;">​</a></h3><p>主程序依赖 <code>Microsoft.Office.Interop.PowerPoint</code> 与本机 Office COM 组件通信。如果你没装 PowerPoint，PPT 联动功能会被禁用，但应用本身仍能运行——PPTManager 里有回退逻辑。</p><h3 id="调试时插件无法加载" tabindex="-1">调试时插件无法加载 <a class="header-anchor" href="#调试时插件无法加载" aria-label="Permalink to &quot;调试时插件无法加载&quot;">​</a></h3><p>插件目录默认是 <code>&lt;程序目录&gt;/Plugins</code>。Debug 构建时是 <code>Ink Canvas\\bin\\Debug\\net6.0-windows10.0.19041.0\\Plugins\\</code>。确保：</p><ol><li>插件文件夹存在</li><li>里面有有效的 <code>manifest.json</code></li><li>日志里没有 <code>PluginCompatibility</code> 报错</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./solution-layout">解决方案结构</a> — 6 个项目各自做什么</li><li><a href="./build-and-run">构建与运行</a> — 版本号、打包、CI</li></ul>`,40))])}const f=t(p,[["render",h]]);export{v as __pageData,f as default};
